var archivosSeleccionadosObj={files:[]};var seccionLista=null;var contenedorLista=null;$(document).on("WebPlayerSeIniciaSistema",function(){seccionLista=document.querySelector('.list-section')
contenedorLista=document.querySelector('.list')
var areaSoltarArchivos=document.querySelector('.drop-section')
var selectorArchivo=document.querySelector('.file-selector')
var selectorArchivoInput=document.querySelector('.file-selector-input')
var documentosSeleccionadaso=document.querySelector("#document-images");documentosSeleccionadaso.addEventListener("click",(e)=>{var target=e.target;var botonEliminar=target.closest(".delete-document");var documentos=target.closest("#document-images");var documentoSeleccionado=target.closest(".document-file");var vistaPreviaDocumento=target.closest(".preview-document");if(documentoSeleccionado===null){return;}
var nombreArchivo=documentoSeleccionado.id;[...archivosSeleccionadosObj.files.map(f=>f.file)].forEach((file)=>{if(file.name===nombreArchivo){if(botonEliminar!=null){archivosSeleccionadosObj.files.splice(archivosSeleccionadosObj.files.map(f=>f.file).indexOf(file),1);documentos.removeChild(documentoSeleccionado);return;}
if(vistaPreviaDocumento!=null){var objeto=archivosSeleccionadosObj.files[archivosSeleccionadosObj.files.map(f=>f.file).indexOf(file)];var archivo=base64ABlob(objeto.base64,objeto.file.type);VistaPreviaArchivo(archivo);}}});});selectorArchivo.onclick=()=>selectorArchivoInput.click()
selectorArchivoInput.onchange=(e)=>{[...selectorArchivoInput.files].forEach((file)=>{if(ValidarTipoArchivo(file)){CargarArchivo(file)}})
var target=e.target||e.srcElement||{};target.value="";}
areaSoltarArchivos.ondragover=(e)=>{e.preventDefault();};areaSoltarArchivos.ondragleave=()=>{areaSoltarArchivos.classList.remove('drag-over-effect')}
areaSoltarArchivos.ondrop=(e)=>{e.preventDefault();areaSoltarArchivos.classList.remove('drag-over-effect')
if(e.dataTransfer.items){[...e.dataTransfer.items].forEach((item)=>{if(item.kind==='file'){var file=item.getAsFile();if(ValidarTipoArchivo(file)){CargarArchivo(file)}}})}else{[...e.dataTransfer.files].forEach((file)=>{if(ValidarTipoArchivo(file)){CargarArchivo(file)}})}};function ValidarTipoArchivo(file){var variableTiposArchivo=Ciel.MPC.WebPlayer.manejadorVariables.ObtenerVariable("{Variable.Usuario.TiposArchivo}");var maxtamanoArchivo=Ciel.MPC.WebPlayer.manejadorVariables.ObtenerVariable("{Variable.Usuario.TamanoArchivo}");var mensajeTipoarchivo="Tipo archivos no definidos";var mensajeTamanoArchivos="Tamaño archivos no definidos";if(variableTiposArchivo==null||variableTiposArchivo==undefined){alert(mensajeTipoarchivo)
return false;}
if(typeof variableTiposArchivo.Valor==='string'&&variableTiposArchivo.Valor.trim()===''){alert(mensajeTipoarchivo)
return false;}
if(maxtamanoArchivo==null||maxtamanoArchivo==undefined){alert(mensajeTamanoArchivos)
return false;}
if(typeof maxtamanoArchivo.Valor==='string'&&maxtamanoArchivo.Valor.trim()===''){alert(mensajeTamanoArchivos)
return false;}
var tiposArchivos=variableTiposArchivo.Valor.split('|');var extensionesArchivo=tiposArchivos.map(element=>element.replace('.','').toUpperCase());var extensionArchivo=file.name.split('.').pop().toUpperCase();var permitirTodosArchivos=false;if(extensionesArchivo.length==1&&extensionesArchivo[0]=='*'){permitirTodosArchivos=true;}
if(!permitirTodosArchivos&&!extensionesArchivo.includes(extensionArchivo)){alert("Archivo no permitido");return false;}
var tamanoFile=$(file.size/(1024*1024));if(tamanoFile[0]>maxtamanoArchivo.Valor){alert("Tamaño máximo de archivo superado");return false;}
return true;};});function base64ABlob(archivoBase64,mimeType){var byteString=atob(archivoBase64.split(',')[1]);var ab=new ArrayBuffer(byteString.length);var ia=new Uint8Array(ab);for(var i=0;i<byteString.length;i++){ia[i]=byteString.charCodeAt(i);}
return new Blob([ab],{type:mimeType});}
function VistaPreviaArchivo(file){var url=window.URL.createObjectURL(file);var xhr=new XMLHttpRequest();xhr.open('GET',url,true);xhr.responseType='blob';xhr.onload=function(e){if(this.status==200){var _viewBlob=function(data,contentType){var file=new Blob([data],{type:contentType});if(window.navigator&&window.navigator.msSaveOrOpenBlob){window.navigator.msSaveOrOpenBlob(file);}else{var fileURL=URL.createObjectURL(file);window.open(fileURL,'_blank');}};_viewBlob(this.response,file.type);}else{alert('Error al obtener blob')}};xhr.send();}
function ObtenerArchivoBase64(archivo){var reader=new FileReader();reader.readAsDataURL(archivo);reader.onload=function(){archivosSeleccionadosObj.files.find((x)=>x.file.name===archivo.name).base64=reader.result;};reader.onerror=function(error){alert('Error: ',error);};}
function ListarArchivos(){BorrarElementoListaArchivos();for(var i=0;i<archivosSeleccionadosObj.files.length;i++){CargarArchivo(archivosSeleccionadosObj.files[i].file,true);}}
function CargarArchivo(file,verArchivos){var mensajeCantArchivos="Cantidad archivos no definido";var maxCantArchivos=Ciel.MPC.WebPlayer.manejadorVariables.ObtenerVariable("{Variable.Usuario.CantidadArchivos}");if(maxCantArchivos==null||maxCantArchivos==undefined){alert(mensajeCantArchivos)
return false;}
if(typeof maxCantArchivos.Valor==='string'&&maxCantArchivos.Valor.trim()===''){alert(mensajeCantArchivos)
return false;}
if(archivosSeleccionadosObj.files.length==maxCantArchivos.Valor){alert("Se alcanzó el máximo total de archivos");return;}
seccionLista.style.display='flex'
var li=document.createElement('li')
li.classList.add('complete','document-file');li.id=file.name
li.innerHTML=`

        <div>

            <div class="d-flex gap-3">

                <div class="file-name d-flex">

                    <div class="name">${file.name}</div>

                    <span>0%</span>

                </div>

                <div class="file-progress d-none">

                    <span></span>

                </div>

                <div class="file-size opacity-25 d-none d-sm-block">${(file.size / (1024 * 1024)).toFixed(2)} MB</div>

            </div>

        </div>

        <div class="d-flex gap-2 gap-sm-3 me-1 me-sm-2 me-md-5">

            <div class="d-none">

                <svg xmlns="http://www.w3.org/2000/svg" class="cross" height="20" width="20"><path d="m5.979 14.917-.854-.896 4-4.021-4-4.062.854-.896 4.042 4.062 4-4.062.854.896-4 4.062 4 4.021-.854.896-4-4.063Z"/></svg>

                <svg xmlns="http://www.w3.org/2000/svg" class="tick" height="20" width="20"><path d="m8.229 14.438-3.896-3.917 1.438-1.438 2.458 2.459 6-6L15.667 7Z"/></svg>

            </div>

            <div title="Visualizar archivo">

                <div class="preview-document" style="cursor: pointer !important;" title="Previsualizar">

                    <svg width="20" height="21" viewBox="0 0 20 21" fill="none" xmlns="http://www.w3.org/2000/svg">

                        <path d="M12.2004 10.6077C12.2004 11.8232 11.2151 12.8085 9.99967 12.8085C8.78423 12.8085 7.79892 11.8232 7.79892 10.6077C7.79892 9.3923 8.78423 8.40699 9.99967 8.40699C11.2151 8.40699 12.2004 9.3923 12.2004 10.6077Z" stroke="#2B2D45" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>

                        <path d="M3 10.6077C3.93479 7.6315 6.71528 5.47266 9.99999 5.47266C13.2847 5.47266 16.0652 7.63153 17 10.6078C16.0652 13.584 13.2847 15.7428 10 15.7428C6.71527 15.7428 3.93477 13.584 3 10.6077Z" stroke="#2B2D45" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>

                    </svg>

                </div>

            </div>

            <div id="btnEliminar" title="Eliminar archivo">

                <div class="delete-document" style="cursor: pointer !important;" title="Eliminar">

                    <svg width="20" height="21" viewBox="0 0 20 21" fill="none" xmlns="http://www.w3.org/2000/svg">

                        <path d="M12.2837 8.10938L11.9952 15.6094M8.00481 15.6094L7.71635 8.10938M16.023 5.43485C16.308 5.47789 16.592 5.52393 16.875 5.57295M16.023 5.43485L15.1332 17.0032C15.058 17.9801 14.2434 18.7344 13.2637 18.7344H6.73631C5.75655 18.7344 4.94198 17.9801 4.86683 17.0032L3.97696 5.43485M16.023 5.43485C15.0677 5.29057 14.1013 5.18008 13.125 5.10464M3.125 5.57295C3.40798 5.52393 3.69198 5.47789 3.97696 5.43485M3.97696 5.43485C4.93231 5.29057 5.89874 5.18008 6.875 5.10464M13.125 5.10464V4.3412C13.125 3.35839 12.3661 2.5379 11.3838 2.50648C10.9244 2.49178 10.463 2.48438 10 2.48438C9.53696 2.48438 9.07565 2.49178 8.61618 2.50648C7.63388 2.5379 6.875 3.35839 6.875 4.3412V5.10464M13.125 5.10464C12.0938 5.02496 11.0516 4.98438 10 4.98438C8.94836 4.98438 7.9062 5.02496 6.875 5.10464" stroke="#2B2D45" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round"/>

                    </svg>

                </div>               

            </div>

        </div>

    `
var seccionSoltar=$(".drop-section");if(verArchivos){if(seccionSoltar!=null&&seccionSoltar.length>0){seccionSoltar[0].style.display="none";}
if(li.children[3].id=="btnEliminar"){li.children[3].style.display="none";}
var seccionEncabezado=$(".header-section");if(seccionEncabezado!=null&&seccionEncabezado.length>0){seccionEncabezado[0].style.display="none";}}else{var existeArchivo=archivosSeleccionadosObj.files.map(f=>f.file).find((x)=>x.name===file.name);if(existeArchivo){var elementoArchivo=document.getElementById(file.name);if(elementoArchivo!=null){elementoArchivo.remove()}
var index=archivosSeleccionadosObj.files.map(f=>f.file.name).indexOf(file.name);archivosSeleccionadosObj.files.splice(index,1);}
archivosSeleccionadosObj.files.push({"file":file,"base64":null});ObtenerArchivoBase64(file);}
contenedorLista.prepend(li);li.querySelector('.cross').onclick=()=>xhr.abort();}
function BorrarElementoListaArchivos(){var listaElementos=document.querySelector('#document-images.list');if(!listaElementos?.replaceChildren){return;}
listaElementos.replaceChildren();}
function MostrarControlesCargarArchivos(){archivosSeleccionadosObj={files:[]};BorrarElementoListaArchivos();var seccionSoltar=$(".drop-section");if(seccionSoltar!=null&&seccionSoltar.length>0){seccionSoltar[0].style.display="block";}
var seccionEncabezado=$(".header-section");if(seccionEncabezado!=null&&seccionEncabezado.length>0){seccionEncabezado[0].style.display="block";}}